25	/**
26	 * Verifies that the required identifying fields of an owner request are present and
27	 * non-blank.
28	 *
29	 * <p>Bean Validation on {@link OwnerFieldsDto} already rejects {@code null} values and
30	 * values failing a field's format, but a purely whitespace value can still slip through
31	 * for free-text fields such as address and city. This validator closes that gap by
32	 * treating any missing or blank value as invalid.
33	 */
34	@Component
35	public class OwnerFieldsValidator {
36	
37	    /**
38	     * @param fields the submitted owner fields
39	     * @throws MissingOwnerFieldsException if any required field is missing or blank
40	     */
41	    public void validate(OwnerFieldsDto fields) {
42	        List<String> missing = new ArrayList<>();
43	        checkRequired("firstName", fields.getFirstName(), missing);
44	        checkRequired("lastName", fields.getLastName(), missing);
45	        checkRequired("address", fields.getAddress(), missing);
46	        checkRequired("city", fields.getCity(), missing);
47	        checkRequired("telephone", fields.getTelephone(), missing);
48	        if (!missing.isEmpty()) {
49	            throw new MissingOwnerFieldsException(missing);
50	        }
51	    }
52	
53	    private void checkRequired(String name, String value, List<String> missing) {
54	        if (value == null || value.isBlank()) {
55	            missing.add(name);
56	        }
57	    }
58	}
